INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66411508', 66411508, 'analyze_legacy', 'Kab. Madiun', 'kabkota', 'Dinas Pekerjaan Umum dan Penataan Ruang', 'Jasa Konsultansi Perencanaan Rekonstruksi Jalan Paket 3', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Timur, Madiun (Kab.)', 87000000, 'March 2026', 'APBD', 1, 1, '1 Paket', 'Pekerjaan Perencanaan Rekonstruksi Jalan, mempersiapkan informasi berupa data teknik, biaya, dan rekomendasi bagi Pejabat Pembuat Komitmen (PPK) untuk mencegah tidak terpenuhinya standar-standar sesuai peraturan yang berlaku. Kinerja perencanaan harus memenuhi standar hasil kerja perencanaan yang disyaratkan. Tanggung jawab profesional perencanaan ini tidak hanya pada Penyedia Jasa Konsultansi sebagai perusahaan tetapi juga bagi para Tenaga Ahli perencanaan yang terlibat. Penyedia Jasa Konsultansi dan Tenaga Ahli yang dimaksud selain berpengalaman di bidangnya, harus mempunyai lisensi dalam bentuk sertifikat kualifikasi di bidang teknis jalan.', 'Pekerjaan Perencanaan Rekonstruksi Jalan meliputi lokasi : Ruas Gandul - Kenongorejo (116); Jalan Ruas Sidorejo - Klumutan (057); Jalan Ruas Bajulan - Duren (108); Jalan Ruas Caruban - Morang (003); Jalan Ruas Purworejo - Kedungrejo (054). Dengan melibatkan 2 orang Tenaga Ahli yaitu 1 orang Team Leader dan 1 orang Ahli K3 Konstruksi. 5 Orang Tenaga pendukung yaitu 3 orang surveyor, 2 orang juru gambar dan 1 orang tenaga administrasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2730391);
